#!/usr/bin/env node
/**
 * ThreatForge PR Threat Delta Action
 *
 * Reads a threatforge.yaml from the current branch, calls the ThreatForge
 * CI scan endpoint, and posts a PR comment with the threat delta.
 */

const fs = require("fs");
const path = require("path");
const https = require("https");
const http = require("http");

// ── GitHub Actions helpers ────────────────────────────────────────────────────

function getInput(name) {
  return process.env[`INPUT_${name.toUpperCase().replace(/-/g, "_")}`] || "";
}

function info(msg) {
  process.stdout.write(`::notice::${msg}\n`);
}

function error(msg) {
  process.stdout.write(`::error::${msg}\n`);
}

function setFailed(msg) {
  error(msg);
  process.exit(1);
}

// ── HTTP helper ───────────────────────────────────────────────────────────────

function httpRequest(urlStr, options, body) {
  return new Promise((resolve, reject) => {
    const url = new URL(urlStr);
    const lib = url.protocol === "https:" ? https : http;
    const req = lib.request(
      {
        hostname: url.hostname,
        port: url.port || (url.protocol === "https:" ? 443 : 80),
        path: url.pathname + url.search,
        method: options.method || "GET",
        headers: options.headers || {},
      },
      (res) => {
        let data = "";
        res.on("data", (chunk) => (data += chunk));
        res.on("end", () => {
          if (res.statusCode >= 400) {
            reject(new Error(`HTTP ${res.statusCode}: ${data}`));
          } else {
            try {
              resolve(JSON.parse(data));
            } catch {
              resolve(data);
            }
          }
        });
      },
    );
    req.on("error", reject);
    if (body) req.write(typeof body === "string" ? body : JSON.stringify(body));
    req.end();
  });
}

// ── PR comment ────────────────────────────────────────────────────────────────

async function postPrComment(token, owner, repo, prNumber, body) {
  await httpRequest(
    `https://api.github.com/repos/${owner}/${repo}/issues/${prNumber}/comments`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
        "User-Agent": "threatforge-scan-action",
        Accept: "application/vnd.github+json",
      },
    },
    { body },
  );
}

// ── Format delta as Markdown ──────────────────────────────────────────────────

function formatDelta(delta, modelName) {
  const { added = [], removed = [], modified = [], summary = {} } = delta;
  const lines = [
    "## 🛡️ ThreatForge Threat Delta",
    `**Model:** ${modelName || "Unknown"}`,
    "",
  ];

  if (added.length === 0 && removed.length === 0 && modified.length === 0) {
    lines.push("✅ No threat changes detected.");
    return lines.join("\n");
  }

  lines.push(
    `**Changes:** +${added.length} added · -${removed.length} removed · ~${modified.length} modified`,
    "",
  );

  if (added.length > 0) {
    lines.push("### ➕ New Threats");
    added.slice(0, 10).forEach((t) => {
      lines.push(`- **[${t.severity}]** ${t.name}`);
    });
    if (added.length > 10) lines.push(`_...and ${added.length - 10} more_`);
  }

  if (removed.length > 0) {
    lines.push("\n### ➖ Removed Threats");
    removed.slice(0, 10).forEach((t) => {
      lines.push(`- ~~${t.name}~~`);
    });
  }

  if (modified.length > 0) {
    lines.push("\n### 🔄 Modified Threats");
    modified.slice(0, 5).forEach((m) => {
      lines.push(`- **${m.name}**: ${m.changes?.join(", ") || "updated"}`);
    });
  }

  lines.push(
    "",
    `_Generated by [ThreatForge](${process.env.INPUT_API_URL || ""}) CI scan_`,
  );

  return lines.join("\n");
}

// ── Main ──────────────────────────────────────────────────────────────────────

async function main() {
  const apiUrl = getInput("api-url");
  const apiToken = getInput("api-token");
  const modelPath = getInput("threatmodel-path") || "threatforge.yaml";
  const githubToken = getInput("github-token");

  if (!apiUrl) setFailed("api-url input is required");
  if (!apiToken) setFailed("api-token input is required");

  // Read the threatforge.yaml
  const absPath = path.resolve(process.cwd(), modelPath);
  if (!fs.existsSync(absPath)) {
    info(`No ${modelPath} found — skipping threat scan`);
    process.exit(0);
  }

  const yamlContent = fs.readFileSync(absPath, "utf8");
  info(`Read ${modelPath} (${yamlContent.length} bytes)`);

  // Call ThreatForge CI scan endpoint
  let scanResult;
  try {
    scanResult = await httpRequest(
      `${apiUrl.replace(/\/$/, "")}/api/ci/scan`,
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${apiToken}`,
          "Content-Type": "application/json",
        },
      },
      { content: yamlContent, format: "yaml" },
    );
  } catch (err) {
    setFailed(`ThreatForge scan failed: ${err.message}`);
    return;
  }

  info(
    `Scan complete. Delta: +${scanResult.delta?.added?.length || 0} threats`,
  );

  // Post PR comment if this is a pull request
  const eventName = process.env.GITHUB_EVENT_NAME;
  const prNumber =
    process.env.GITHUB_EVENT_PULL_REQUEST_NUMBER || process.env.PR_NUMBER;
  const [owner, repo] = (process.env.GITHUB_REPOSITORY || "").split("/");

  if (eventName === "pull_request" && prNumber && owner && repo) {
    const comment = formatDelta(scanResult.delta || {}, scanResult.modelName);
    try {
      await postPrComment(githubToken, owner, repo, prNumber, comment);
      info("Posted PR comment with threat delta");
    } catch (err) {
      error(`Failed to post PR comment: ${err.message}`);
      // Don't fail the action — scan succeeded even if comment failed
    }
  } else {
    info("Not a PR event — skipping comment");
    console.log(formatDelta(scanResult.delta || {}, scanResult.modelName));
  }
}

main().catch((err) => {
  setFailed(err.message);
});
